   114→/// Compute the kzg proof given an ssz blob and its kzg commitment.
   115→pub fn compute_blob_kzg_proof<E: EthSpec>(
   116→    kzg: &Kzg,
   117→    blob: &Blob<E>,
   118→    kzg_commitment: KzgCommitment,
   119→) -> Result<KzgProof, KzgError> {
   120→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   121→    kzg.compute_blob_kzg_proof(&kzg_blob, kzg_commitment)
   122→}
   123→
   124→/// Compute the kzg commitment for a given blob.
   125→pub fn blob_to_kzg_commitment<E: EthSpec>(
   126→    kzg: &Kzg,
   127→    blob: &Blob<E>,
   128→) -> Result<KzgCommitment, KzgError> {
   129→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   130→    kzg.blob_to_kzg_commitment(&kzg_blob)
   131→}
   132→
   133→/// Compute the kzg proof for a given blob and an evaluation point z.
   134→pub fn compute_kzg_proof<E: EthSpec>(
   135→    kzg: &Kzg,
   136→    blob: &Blob<E>,
   137→    z: Hash256,
   138→) -> Result<(KzgProof, Hash256), KzgError> {
   139→    let z = z.0.into();
   140→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   141→    kzg.compute_kzg_proof(&kzg_blob, &z)
   142→        .map(|(proof, z)| (proof, Hash256::from_slice(&z.to_vec())))
   143→}
   144→
   145→/// Verify a `kzg_proof` for a `kzg_commitment` that evaluating a polynomial at `z` results in `y`
   146→pub fn verify_kzg_proof<E: EthSpec>(
   147→    kzg: &Kzg,
   148→    kzg_commitment: KzgCommitment,
   149→    kzg_proof: KzgProof,
   150→    z: Hash256,
   151→    y: Hash256,
   152→) -> Result<bool, KzgError> {
   153→    kzg.verify_kzg_proof(kzg_commitment, &z.0.into(), &y.0.into(), kzg_proof)
   154→}
   155→
   156→/// Build data column sidecars from a signed beacon block and its blobs.
   157→#[instrument(skip_all, level = "debug", fields(blob_count = blobs.len()))]
   158→pub fn blobs_to_data_column_sidecars<E: EthSpec>(
   159→    blobs: &[&Blob<E>],
   160→    cell_proofs: Vec<KzgProof>,
   161→    block: &SignedBeaconBlock<E>,
   162→    kzg: &Kzg,
   163→    spec: &ChainSpec,
   164→) -> Result<DataColumnSidecarList<E>, DataColumnSidecarError> {
   165→    if blobs.is_empty() {
   166→        return Ok(vec![]);
   167→    }
   168→
   169→    let kzg_commitments = block
   170→        .message()
   171→        .body()
   172→        .blob_kzg_commitments()
   173→        .map_err(|_err| DataColumnSidecarError::PreDeneb)?;
   174→    let kzg_commitments_inclusion_proof = block.message().body().kzg_commitments_merkle_proof()?;
   175→    let signed_block_header = block.signed_block_header();
   176→
   177→    let proof_chunks = cell_proofs
   178→        .chunks_exact(E::number_of_columns())
   179→        .collect::<Vec<_>>();
   180→
   181→    // NOTE: assumes blob sidecars are ordered by index
   182→    let zipped: Vec<_> = blobs.iter().zip(proof_chunks).collect();
   183→    let blob_cells_and_proofs_vec = zipped
   184→        .into_par_iter()
   185→        .map(|(blob, proofs)| {
   186→            let blob = blob.as_ref().try_into().map_err(|e| {
   187→                KzgError::InconsistentArrayLength(format!(
   188→                    "blob should have a guaranteed size due to FixedVector: {e:?}"
   189→                ))
   190→            })?;
   191→
   192→            kzg.compute_cells(blob).and_then(|cells| {
   193→                let proofs = proofs.try_into().map_err(|e| {
   194→                    KzgError::InconsistentArrayLength(format!(
   195→                        "proof chunks should have exactly `number_of_columns` proofs: {e:?}"
   196→                    ))
   197→                })?;
   198→                Ok((cells, proofs))
   199→            })
   200→        })
   201→        .collect::<Result<Vec<_>, KzgError>>()?;
   202→
   203→    build_data_column_sidecars(
   204→        kzg_commitments.clone(),
   205→        kzg_commitments_inclusion_proof,
   206→        signed_block_header,
   207→        blob_cells_and_proofs_vec,
   208→        spec,
   209→    )
   210→    .map_err(DataColumnSidecarError::BuildSidecarFailed)
   211→}
   212→
   213→pub fn compute_cells<E: EthSpec>(blobs: &[&Blob<E>], kzg: &Kzg) -> Result<Vec<KzgCell>, KzgError> {
   214→    let cells_vec = blobs
   215→        .into_par_iter()
   216→        .map(|blob| {
   217→            let blob: KzgBlobRef<'_> = blob.as_ref().try_into().map_err(|e| {
   218→                KzgError::InconsistentArrayLength(format!(
   219→                    "blob should have a guaranteed size due to FixedVector: {e:?}",
   220→                ))
   221→            })?;
   222→
   223→            kzg.compute_cells(blob)
   224→        })
   225→        .collect::<Result<Vec<_>, KzgError>>()?;
   226→
   227→    let cells_flattened: Vec<KzgCell> = cells_vec.into_iter().flatten().collect();
   228→    Ok(cells_flattened)
   229→}
   230→
   231→pub(crate) fn build_data_column_sidecars<E: EthSpec>(
   232→    kzg_commitments: KzgCommitments<E>,
   233→    kzg_commitments_inclusion_proof: FixedVector<Hash256, E::KzgCommitmentsInclusionProofDepth>,
   234→    signed_block_header: SignedBeaconBlockHeader,
   235→    blob_cells_and_proofs_vec: Vec<CellsAndKzgProofs>,
   236→    spec: &ChainSpec,
   237→) -> Result<DataColumnSidecarList<E>, String> {
   238→    let number_of_columns = E::number_of_columns();
   239→    let max_blobs_per_block = spec
   240→        .max_blobs_per_block(signed_block_header.message.slot.epoch(E::slots_per_epoch()))
   241→        as usize;
   242→    let mut columns = vec![Vec::with_capacity(max_blobs_per_block); number_of_columns];
   243→    let mut column_kzg_proofs = vec![Vec::with_capacity(max_blobs_per_block); number_of_columns];
   244→
   245→    for (blob_cells, blob_cell_proofs) in blob_cells_and_proofs_vec {
   246→        // we iterate over each column, and we construct the column from "top to bottom",
   247→        // pushing on the cell and the corresponding proof at each column index. we do this for
   248→        // each blob (i.e. the outer loop).
   249→        for col in 0..number_of_columns {
   250→            let cell = blob_cells
   251→                .get(col)
   252→                .ok_or(format!("Missing blob cell at index {col}"))?;
   253→            let cell: Vec<u8> = cell.to_vec();
   254→            let cell = Cell::<E>::from(cell);
   255→
   256→            let proof = blob_cell_proofs
   257→                .get(col)
   258→                .ok_or(format!("Missing blob cell KZG proof at index {col}"))?;
   259→
   260→            let column = columns
   261→                .get_mut(col)
   262→                .ok_or(format!("Missing data column at index {col}"))?;
   263→            let column_proofs = column_kzg_proofs
   264→                .get_mut(col)
   265→                .ok_or(format!("Missing data column proofs at index {col}"))?;
   266→
   267→            column.push(cell);
   268→            column_proofs.push(*proof);
   269→        }
   270→    }
   271→
   272→    let sidecars: Vec<Arc<DataColumnSidecar<E>>> = columns
   273→        .into_iter()
   274→        .zip(column_kzg_proofs)
   275→        .enumerate()
   276→        .map(|(index, (col, proofs))| {
   277→            Arc::new(DataColumnSidecar {
   278→                index: index as u64,
   279→                column: DataColumn::<E>::from(col),
   280→                kzg_commitments: kzg_commitments.clone(),
   281→                kzg_proofs: VariableList::from(proofs),
   282→                signed_block_header: signed_block_header.clone(),
   283→                kzg_commitments_inclusion_proof: kzg_commitments_inclusion_proof.clone(),
   284→            })
   285→        })
   286→        .collect();
   287→
   288→    Ok(sidecars)
   289→}
   290→
   291→/// Reconstruct blobs from a subset of data column sidecars (requires at least 50%).
   292→///
   293→/// If `blob_indices_opt` is `None`, this function attempts to reconstruct all blobs associated
   294→/// with the block.
   295→pub fn reconstruct_blobs<E: EthSpec>(
   296→    kzg: &Kzg,
   297→    data_columns: &[Arc<DataColumnSidecar<E>>],
   298→    blob_indices_opt: Option<Vec<u64>>,
   299→    signed_block: &SignedBlindedBeaconBlock<E>,
   300→    spec: &ChainSpec,
   301→) -> Result<BlobSidecarList<E>, String> {
   302→    // The data columns are from the database, so we assume their correctness.
   303→    let first_data_column = data_columns
   304→        .first()
   305→        .ok_or("data_columns should have at least one element".to_string())?;
   306→
   307→    let blob_indices: Vec<usize> = match blob_indices_opt {
   308→        Some(indices) => indices.into_iter().map(|i| i as usize).collect(),
   309→        None => {
   310→            let num_of_blobs = first_data_column.kzg_commitments.len();
   311→            (0..num_of_blobs).collect()
   312→        }
   313→    };
   314→
   315→    let blob_sidecars = blob_indices
   316→        .into_par_iter()
   317→        .map(|row_index| {
   318→            let mut cells: Vec<KzgCellRef> = vec![];
   319→            let mut cell_ids: Vec<u64> = vec![];
   320→            for data_column in data_columns {
   321→                let cell = data_column
   322→                    .column
   323→                    .get(row_index)
   324→                    .ok_or(format!("Missing data column at row index {row_index}"))
   325→                    .and_then(|cell| {
   326→                        ssz_cell_to_crypto_cell::<E>(cell).map_err(|e| format!("{e:?}"))
   327→                    })?;
   328→
   329→                cells.push(cell);
   330→                cell_ids.push(data_column.index);
   331→            }
   332→
   333→            let (cells, _kzg_proofs) = kzg
   334→                .recover_cells_and_compute_kzg_proofs(&cell_ids, &cells)
   335→                .map_err(|e| format!("Failed to recover cells and compute KZG proofs: {e:?}"))?;
   336→
   337→            let num_cells_original_blob = cells.len() / 2;
   338→            let blob_bytes = cells
   339→                .into_iter()
   340→                .take(num_cells_original_blob)
   341→                .flat_map(|cell| cell.into_iter())
   342→                .collect();
   343→
   344→            let blob = Blob::<E>::new(blob_bytes).map_err(|e| format!("{e:?}"))?;
   345→            let kzg_proof = KzgProof::empty();
   346→
   347→            BlobSidecar::<E>::new_with_existing_proof(
   348→                row_index,
   349→                blob,
   350→                signed_block,
   351→                first_data_column.signed_block_header.clone(),
   352→                &first_data_column.kzg_commitments_inclusion_proof,
   353→                kzg_proof,
   354→            )
   355→            .map(Arc::new)
   356→            .map_err(|e| format!("{e:?}"))
   357→        })
   358→        .collect::<Result<Vec<_>, _>>()?;
   359→
   360→    let max_blobs = spec.max_blobs_per_block(signed_block.epoch()) as usize;
   361→
   362→    BlobSidecarList::new(blob_sidecars, max_blobs).map_err(|e| format!("{e:?}"))
   363→}
   364→
   365→/// Reconstruct all data columns from a subset of data column sidecars (requires at least 50%).
   366→pub fn reconstruct_data_columns<E: EthSpec>(
   367→    kzg: &Kzg,
   368→    mut data_columns: Vec<Arc<DataColumnSidecar<E>>>,
   369→    spec: &ChainSpec,
   370→) -> Result<DataColumnSidecarList<E>, KzgError> {
   371→    // Sort data columns by index to ensure ascending order for KZG operations
   372→    data_columns.sort_unstable_by_key(|dc| dc.index);
   373→
   374→    let first_data_column = data_columns
   375→        .first()
   376→        .ok_or(KzgError::InconsistentArrayLength(
   377→            "data_columns should have at least one element".to_string(),
   378→        ))?;
   379→
   380→    let num_of_blobs = first_data_column.kzg_commitments.len();
   381→
   382→    let blob_cells_and_proofs_vec =
   383→        (0..num_of_blobs)
   384→            .into_par_iter()
   385→            .map(|row_index| {
   386→                let mut cells: Vec<KzgCellRef> = vec![];
   387→                let mut cell_ids: Vec<u64> = vec![];
   388→                for data_column in &data_columns {
   389→                    let cell = data_column.column.get(row_index).ok_or(
   390→                        KzgError::InconsistentArrayLength(format!(
   391→                            "Missing data column at row index {row_index}"
   392→                        )),
   393→                    )?;
   394→
   395→                    cells.push(ssz_cell_to_crypto_cell::<E>(cell)?);
   396→                    cell_ids.push(data_column.index);
   397→                }
   398→                kzg.recover_cells_and_compute_kzg_proofs(&cell_ids, &cells)
   399→            })
   400→            .collect::<Result<Vec<_>, KzgError>>()?;
   401→
   402→    // Clone sidecar elements from existing data column, no need to re-compute
   403→    build_data_column_sidecars(
   404→        first_data_column.kzg_commitments.clone(),
   405→        first_data_column.kzg_commitments_inclusion_proof.clone(),
   406→        first_data_column.signed_block_header.clone(),
   407→        blob_cells_and_proofs_vec,
   408→        spec,
   409→    )
   410→    .map_err(KzgError::ReconstructFailed)
   411→}
